"""Tests for ``return_pass.py`` (P34.29; B3 §3.13 row M5 / V6; SIG-MEM-010).

Each test builds a small committed-input tree in ``tmp_path`` — a LEDGER with a
``## CURRENT STATE`` block and a ``### RETURN PASS — current`` region, a
``return_pass.toml`` map, an ``events.jsonl``, a ``DEFERRALS.md``, a manifest
chain stub and the disposition/plan CSVs — then runs the real CLI. Every test
asserts a file, a row or an exit code that a no-op check (exit 0, nothing
verified) cannot produce, so every test fails against a no-op. Nothing here
asserts the living records' current contents (OM-15); the last test runs
``check`` on the real tree, which must stay green — the invariant, not a value.

Run::

    uv run pytest docs/build/tools/test_return_pass.py -q
"""

from __future__ import annotations

import csv
import io
import json
import os
import subprocess
import sys
import textwrap
from pathlib import Path

import pytest

