TOOL = HERE / "return_pass.py"
REPO = HERE.parents[2]
PYTHON = os.environ.get("SIG_TOOLS_PYTHON") or sys.executable
PD = "docs/build/planning/2026-09-30-next-phase"
MAP_REL = "docs/build/tools/record_policy/return_pass.toml"

