def render_fixture_region(map_text: str) -> str:
    """Ask the real tool for the rendered region — the fixture LEDGER embeds
    the generated bytes verbatim (no hand-keyed copy that could drift)."""
    import importlib.util
    import tomllib

    spec = importlib.util.spec_from_file_location("return_pass", TOOL)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod.render_region(tomllib.loads(map_text))


def make_tree(
    root: Path,
    map_text: str = BASE_MAP,
    events: list[dict] | None = None,
    deferral_rows: list[str] | None = None,
    universe: list[dict[str, str]] | None = None,
    region: str | None = None,
    rp_value: str | None = None,
) -> Path:
    if events is None:
        events = [
            event("D-X-1", "OPEN", landing="P9.11", owner="the OM-19 leg-runner"),
            event("D-X-2", "OPEN", landing="P9.10's leg", owner="engineering"),
        ]
    if deferral_rows is None:
        deferral_rows = [
            deferral_row("D-X-1", "owner: the OM-19 leg-runner · trigger: the go"),
            deferral_row("D-X-2", "owner: engineering · trigger: a window"),
        ]
    if universe is None:
        universe = [
            uni_row("D-X-1", "live-return-pass(R11-FIX-01)"),
            uni_row("D-X-2", "live-return-pass(R11-FIX-02)"),
        ]
    if region is None:
        region = render_fixture_region(map_text)
    if rp_value is None:
        rp_value = "P9.9, P9.10"
    files = {
        "docs/build/LEDGER.md": LEDGER_TEMPLATE.format(rp=rp_value, region=region),
        MAP_REL: map_text.lstrip("\n"),
        "docs/tickets/00_MANIFEST.md": MANIFEST,
        "docs/tickets/DEFERRALS.md": DEFERRALS.format(rows="\n".join(deferral_rows)),
        "docs/build/reports/obligations/events.jsonl": "".join(
            json.dumps(e, ensure_ascii=False) + "\n" for e in events
        ),
        f"{PD}/universe/UNIVERSE_DISPOSED.csv": _csv(UNI_COLS, universe),
        f"{PD}/data/round11_plan.csv": _csv(
            PLAN_COLS,
            [
                {"row": "3", "id": "P9.11", "cat_ids": "R11-FIX-01"},
                {"row": "2", "id": "P9.10", "cat_ids": "R11-FIX-02"},
            ],
        ),
    }
    for rel, text in files.items():
        p = root / rel
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(text, encoding="utf-8")
    return root


def run(root: Path, *args: str) -> subprocess.CompletedProcess[str]:
    return subprocess.run(
        [PYTHON, str(TOOL), *args, "--root", str(root)],
        capture_output=True,
        text=True,
        check=False,
    )


def test_check_passes_on_a_consistent_fixture(tmp_path: Path) -> None:
    make_tree(tmp_path)
    res = run(tmp_path, "check")
    assert res.returncode == 0, res.stderr
    assert "evaluated" in res.stdout


def test_generate_reproduces_the_region_and_key_byte_for_byte(tmp_path: Path) -> None:
    # the region in the fixture is the tool's own render, so check must pass
    # before and after generate (byte-for-byte both ways)
    make_tree(tmp_path)
    before = (tmp_path / "docs/build/LEDGER.md").read_text()
    res = run(tmp_path, "generate")
    assert res.returncode == 0, res.stderr
    assert "in sync" in res.stdout
    assert (tmp_path / "docs/build/LEDGER.md").read_text() == before
    res = run(tmp_path, "check")
    assert res.returncode == 0, res.stderr


def test_byte_drift_in_the_table_fails(tmp_path: Path) -> None:
    make_tree(tmp_path)
    ledger = tmp_path / "docs/build/LEDGER.md"
    text = ledger.read_text()
    assert "hosted capture; IN-TICKET PAUSE" in text
    ledger.write_text(text.replace("hosted capture", "HAND-EDITED capture"))
    res = run(tmp_path, "check")
    assert res.returncode == 1
    assert "byte-for-byte" in res.stderr or "generated" in res.stderr


def test_key_table_disagreement_fails(tmp_path: Path) -> None:
    make_tree(tmp_path, rp_value="P9.9, P9.10, P9.17")
    res = run(tmp_path, "check")
    assert res.returncode == 1
    assert "returnPass" in res.stderr


def test_unsorted_key_fails(tmp_path: Path) -> None:
    # natural ticket order P9.9 before P9.10 — a swapped key is drift
    make_tree(tmp_path, rp_value="P9.10, P9.9")
    res = run(tmp_path, "check")
    assert res.returncode == 1
    assert "returnPass" in res.stderr


def test_owed_obligation_with_no_home_fails(tmp_path: Path) -> None:
    make_tree(
        tmp_path,
        events=[
            event("D-X-1", "OPEN"),
            event("D-X-2", "OPEN"),
            event("D-ORPHAN-1", "OPEN", landing="a hand-wave", owner="nobody"),
        ],
        deferral_rows=[
            deferral_row("D-X-1", "owner: x · trigger: y"),
            deferral_row("D-X-2", "owner: x · trigger: y"),
            deferral_row("D-ORPHAN-1", "someone, somehow"),
        ],
    )
    res = run(tmp_path, "check")
    assert res.returncode == 1
    assert "D-ORPHAN-1" in res.stderr
    assert "no home" in res.stderr


def test_two_homes_fails(tmp_path: Path) -> None:
    # D-X-1 sits in the RETURN PASS table AND carries a ticket() disposition —
    # two homes (it must be live-return-pass or no disposition)
    make_tree(
        tmp_path,
        universe=[
            uni_row("D-X-1", "ticket(R11-FIX-02)"),
            uni_row("D-X-2", "ticket(R11-FIX-02)"),
        ],
    )
    res = run(tmp_path, "check")
    assert res.returncode == 1
    assert "two homes" in res.stderr


def test_live_return_pass_without_a_row_fails(tmp_path: Path) -> None:
    # D-X-1's disposition routes it to RETURN PASS but no row names it
    map_text = BASE_MAP.replace('obligations = ["D-X-1"]', 'obligations = []').replace(
        "obligations_cell = '''D-X-1'''", "obligations_cell = '''(fixture row, empty)'''"
    )
    make_tree(tmp_path, map_text=map_text)
    res = run(tmp_path, "check")
    assert res.returncode == 1
    assert "live-return-pass" in res.stderr and "no RETURN PASS row" in res.stderr


def test_queued_leg_renders_window_go_and_rerun(tmp_path: Path) -> None:
    make_tree(tmp_path)
    res = run(tmp_path, "check")
    assert res.returncode == 0, res.stderr
    region = (tmp_path / "docs/build/LEDGER.md").read_text()
    # the queued leg's window, go id and re-run line are rendered in the row
    assert "03:00–10:00Z" in region
    assert "S5-3" in region
    assert "implement-spec spec=docs/tickets/002_P9.10__second.md" in region


def test_leg_field_outside_the_cells_fails(tmp_path: Path) -> None:
    map_text = BASE_MAP.replace('rerun = "implement-spec spec=', 'rerun = "bogus-cmd spec=')
    make_tree(tmp_path, map_text=map_text)
    res = run(tmp_path, "check")
    assert res.returncode == 1
    assert "re-run line" in res.stderr


