def test_ticket_disposition_resolving_to_no_row_fails(tmp_path: Path) -> None:
    # D-X-3's ticket(R11-NOPE-9) cites a catalog unit that lands no chain row
    make_tree(
        tmp_path,
        events=[
            event("D-X-1", "OPEN"),
            event("D-X-2", "OPEN"),
            event("D-X-3", "OPEN", landing="P9.17"),
        ],
        deferral_rows=[
            deferral_row("D-X-1", "owner: x · trigger: y"),
            deferral_row("D-X-2", "owner: x · trigger: y"),
            deferral_row("D-X-3", "owner: x · trigger: y"),
        ],
        universe=[
            uni_row("D-X-1", "live-return-pass(R11-FIX-01)"),
            uni_row("D-X-2", "live-return-pass(R11-FIX-02)"),
            uni_row("D-X-3", "ticket(R11-NOPE-9)"),
        ],
    )
    res = run(tmp_path, "check")
    assert res.returncode == 1
    assert "resolves to no manifest chain row" in res.stderr


def test_watch_home_passes(tmp_path: Path) -> None:
    # an upstream-release watch with no disposition and no manifest row — its
    # DEFERRALS owner:/trigger:/due: bound is its recorded home
    make_tree(
        tmp_path,
        events=[
            event("D-X-1", "OPEN"),
            event("D-X-2", "OPEN"),
            event("D-WATCH-1", "OPEN", landing="an upstream release"),
        ],
        deferral_rows=[
            deferral_row("D-X-1", "owner: x · trigger: y"),
            deferral_row("D-X-2", "owner: x · trigger: y"),
            deferral_row("D-WATCH-1", "owner: upstream · trigger: a release >1.0"),
        ],
    )
    res = run(tmp_path, "check")
    assert res.returncode == 0, res.stderr


def test_vacuous_is_an_error(tmp_path: Path) -> None:
    make_tree(tmp_path, events=[], deferral_rows=[])
    res = run(tmp_path, "check")
    assert res.returncode == 3
    assert "VACUOUS" in res.stderr


def test_check_on_the_real_tree_is_green() -> None:
    res = subprocess.run(
        [PYTHON, str(TOOL), "check", "--root", str(REPO)],
        capture_output=True,
        text=True,
        check=False,
    )
    assert res.returncode == 0, res.stderr
    assert "evaluated" in res.stdout


def test_module_sort_is_natural() -> None:
    import importlib.util

    spec = importlib.util.spec_from_file_location("return_pass", TOOL)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    ordered = sorted(
        ["P34.17", "P34.6", "P21.5", "P34.21a", "P9.10"], key=mod.ticket_sort_key
    )
    assert ordered == ["P9.10", "P21.5", "P34.6", "P34.17", "P34.21a"]
